compile.workshop:
variables {
    global:
        0: g
        1: h
}

rule ("constant folding") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 0.141120008059867);
        Set Global Variable(g, 0.877582561890372);
        Set Global Variable(g, 0.052335956242943);
        Set Global Variable(g, 0.500000000000000);
        Set Global Variable(g, 1.732050807568877);
        Set Global Variable(g, 0);
        Set Global Variable(g, 2);
        Set Global Variable(g, 4);
        Set Global Variable(g, 5);
        Set Global Variable(g, Magnitude Of(Global.h));
        Set Global Variable(g, Magnitude Of(Global.h));
        Set Global Variable(g, 32);
        Set Global Variable(g, 1.414213562373095);
        Set Global Variable(g, Left);
        Set Global Variable(g, Vector(0, 0, 0));
        Set Global Variable(g, Magnitude Of(Global.h));
        Set Global Variable(g, Team 2);
        Set Global Variable(g, Team 1);
        Set Global Variable(g, All Teams);
        Set Global Variable(g, False);
        Set Global Variable(g, Custom String("bcd"));
        Set Global Variable(g, Custom String("bANANa"));
        Set Global Variable(g, 2);
        Set Global Variable(g, -1);
        Set Global Variable(g, Index Of Array Value(Array(1, Global.h, 3), 3));
        Set Global Variable(g, -1);
        Set Global Variable(g, Empty Array);
        Set Global Variable(g, Array(2, 3));
        Set Global Variable(g, 0.333333333333333);
        Set Global Variable(g, 0.123456789012345);
        Set Global Variable(g, -0.666666666666666);
    }
}

